CREATE TABLE activation_requests (id UUID PRIMARY KEY, external_id VARCHAR(100) NOT NULL UNIQUE, owner_client_id VARCHAR(100) NOT NULL, customer_id VARCHAR(100) NOT NULL, product_code VARCHAR(80) NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, version BIGINT NOT NULL DEFAULT 0, CONSTRAINT ck_activation_requests_status CHECK (status IN ('PENDING','PROCESSING','COMPLETED','FAILED')));
CREATE TABLE activation_tasks (id UUID PRIMARY KEY, request_id UUID NOT NULL UNIQUE REFERENCES activation_requests(id), status VARCHAR(20) NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, available_at TIMESTAMPTZ NOT NULL, locked_until TIMESTAMPTZ, claim_token UUID, last_error VARCHAR(1000), created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, version BIGINT NOT NULL DEFAULT 0, CONSTRAINT ck_activation_tasks_status CHECK (status IN ('PENDING','PROCESSING','COMPLETED','FAILED')));
